import java.io.*;
import java.net.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String tenantId = req.getHeader("X-Tenant-ID");

        if (reportId == null || tenantId == null) {
            resp.sendError(400, "Missing parameters");
            return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Build query with tenant isolation
            String query = "SELECT r.title, r.content, r.created_at, u.email " +
                          "FROM reports r JOIN users u ON r.author_id = u.id " +
                          "WHERE r.tenant_id = '" + tenantId + "' " +
                          "AND r.id = " + reportId;

            if (format != null && !format.isEmpty()) {
                query += " AND r.format = '" + format + "'";
            }

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("title", rs.getString("title"));
                row.put("content", rs.getString("content"));
                row.put("created_at", rs.getString("created_at"));
                row.put("email", rs.getString("email"));
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());
        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String tenantId = req.getHeader("X-Tenant-ID");
        BufferedReader reader = req.getReader();
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            body.append(line);
        }

        JSONObject payload = new JSONObject(body.toString());
        String title = payload.optString("title", "");
        String content = payload.optString("content", "");
        String authorEmail = payload.optString("author_email", "");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Lookup author by email within tenant
            String lookupSql = "SELECT id FROM users WHERE tenant_id = '" + tenantId +
                             "' AND email = '" + authorEmail + "'";
            Statement lookupStmt = conn.createStatement();
            ResultSet lookupRs = lookupStmt.executeQuery(lookupSql);

            if (!lookupRs.next()) {
                resp.sendError(404, "Author not found");
                return;
            }
            int authorId = lookupRs.getInt("id");

            // Insert report - uses PreparedStatement here
            String insertSql = "INSERT INTO reports (tenant_id, author_id, title, content) VALUES (?, ?, ?, ?)";
            PreparedStatement pstmt = conn.prepareStatement(insertSql);
            pstmt.setString(1, tenantId);
            pstmt.setInt(2, authorId);
            pstmt.setString(3, title);
            pstmt.setString(4, content);
            pstmt.executeUpdate();

            resp.setStatus(201);
            resp.getWriter().write("{\"status\": \"created\"}");
        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }
}
